CREATE POLICY galeria_admin_select ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'galeria' AND (public.puede_editar(auth.uid(), 'galeria') OR public.puede_editar(auth.uid(), 'materias') OR public.puede_editar(auth.uid(), 'avisos')));
CREATE POLICY galeria_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'galeria' AND ((name LIKE 'galeria/%' AND public.puede_editar(auth.uid(), 'galeria')) OR (name LIKE 'especialidades/%' AND public.puede_editar(auth.uid(), 'materias')) OR (name LIKE 'avisos/%' AND public.puede_editar(auth.uid(), 'avisos'))));
CREATE POLICY galeria_admin_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'galeria' AND ((name LIKE 'galeria/%' AND public.puede_editar(auth.uid(), 'galeria')) OR (name LIKE 'especialidades/%' AND public.puede_editar(auth.uid(), 'materias')) OR (name LIKE 'avisos/%' AND public.puede_editar(auth.uid(), 'avisos'))));
CREATE POLICY galeria_published_read ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'galeria' AND (EXISTS (SELECT 1 FROM public.fotos f JOIN public.albumes a ON a.id=f.album_id WHERE f.url = 'storage:' || storage.objects.name AND f.publicado AND a.publicado) OR EXISTS (SELECT 1 FROM public.especialidades e WHERE e.imagen_url = 'storage:' || storage.objects.name) OR EXISTS (SELECT 1 FROM public.avisos av WHERE av.imagen_url = 'storage:' || storage.objects.name AND av.publicado)));
ALTER TABLE public.fotos ADD CONSTRAINT fotos_tipo_valid CHECK (tipo IN ('foto','video'));
ALTER TABLE public.oportunidades ADD CONSTRAINT oportunidades_tipo_valid CHECK (tipo IN ('pasantia','empleo'));